// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.util.concurrent.Callable;
import java.util.function.Consumer;

/**
 * Runs the applier's heavy, stateless work (sealing, generation preparation, base scans, range merges) off the applier
 * thread. The completion callback runs on the worker thread and must only hand the outcome back to the applier.
 */
interface AdjacencyWorkerPool {

	final class Outcome<T> {
		private final T result;
		private final Throwable failure;

		private Outcome(T result, Throwable failure) {
			this.result = result;
			this.failure = failure;
		}

		static <T> Outcome<T> success(T result) {
			return new Outcome<>(result, null);
		}

		static <T> Outcome<T> failure(Throwable failure) {
			return new Outcome<>(null, failure);
		}

		boolean succeeded() {
			return failure == null;
		}

		T result() {
			return result;
		}

		Throwable failure() {
			return failure;
		}
	}

	<T> void submit(Callable<T> work, Consumer<Outcome<T>> onDone);

	void shutdown();
}
